head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/list_common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");
scwin.vScrenID = "ULDFIS00100_P2.gfm";
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};

/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_StdIndList.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    return true;
};


/**
 * 업종목록 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 필수 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    //ShowWin(grd_StdIndList);

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.stdIndList_p" + "&outputMessageId=FIS_STD_IND_LIST_P";
    dts_StdIndList.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_StdIndList.Reset();
};


/**
 * 선택된 값을 오프너에 전달한다.
 */
scwin.fn_SetParam = function(v_Currow) {
    if (v_Currow == undefined) {
        v_Currow = dts_StdIndList.getRowPosition();
    }
    var arrPar = new Array();
    arrPar[0] = {
        STD_IND_CD: dts_StdIndList.getCellData(v_Currow, "STD_IND_CD"), //업종코드	
        STD_IND_NM: dts_StdIndList.getCellData(v_Currow, "STD_IND_NM") //업종명
    };

	//----W-Craft WebSquare 변환 확인: fn_SetParStdIndCd----//
    opener.fn_SetParStdIndCd(arrPar);
    scwin.fn_CloseFrame();
};


/**
 * close frame
 */
scwin.fn_CloseFrame = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_StdIndList_OnLoadError = function() {
    $c.stf.alert_error(dts_StdIndList);
};
scwin.dts_StdIndList_OnLoadCompleted = function(rowcount) {
    // 데이터셋 OnLoadCompleted
    if (dts_StdIndList.errorMsg) {
        alert(dts_StdIndList.errorMsg);
    }
};
scwin.gform_onload = function() {
    // form onload
    $c.libRoundPanel.PanelToGroupBox(panel_Top); // 패널라운드 처리	

    // 업종 조회
    scwin.fn_Search();
};
scwin.img_Close_onclick = function() {
    // 닫기버튼 클릭
    scwin.fn_CloseFrame();
};
scwin.img_Confirm_onclick = function() {
    // 확인버튼 클릭
    scwin.fn_SetParam();
};
scwin.trv_StdInd_OnDblClick = function() {
    scwin.fn_SetParam();
};
